from functools import cmp_to_key


def _parse(version):
    main_and_build = version.split('+', 1)
    main = main_and_build[0]

    if '-' in main:
        core, prerelease = main.split('-', 1)
        pre = prerelease.split('.')
    else:
        core = main
        pre = []

    major, minor, patch = (int(part) for part in core.split('.'))
    return ((major, minor, patch), pre)


def _compare_identifiers(a, b):
    a_is_number = a.isdigit()
    b_is_number = b.isdigit()

    if a_is_number and b_is_number:
        a_value = int(a)
        b_value = int(b)
        return (a_value > b_value) - (a_value < b_value)
    if a_is_number:
        return -1
    if b_is_number:
        return 1
    return (a > b) - (a < b)


def _compare_versions(a, b):
    a_core, a_pre = _parse(a)
    b_core, b_pre = _parse(b)

    if a_core != b_core:
        return (a_core > b_core) - (a_core < b_core)

    if not a_pre and not b_pre:
        return 0
    if not a_pre:
        return 1
    if not b_pre:
        return -1

    for a_id, b_id in zip(a_pre, b_pre):
        result = _compare_identifiers(a_id, b_id)
        if result:
            return result

    return (len(a_pre) > len(b_pre)) - (len(a_pre) < len(b_pre))


def sort_versions(vs):
    """Return semantic version strings sorted by SemVer 2.0.0 precedence."""
    return sorted(vs, key=cmp_to_key(_compare_versions))
